function lifeInWeeks(age) {
    var yearsRemaining = 90 - age;
    var days = yearsRemaining * 365;
    var weeks = yearsRemaining * 52;
    var months = yearsRemaining * 12;
    console.log("You have " + days + " days, " + weeks + " weeks, and " + months + " months left.");
}
lifeInWeeks(12);   // You have 28470 days, 4056 weeks, and 936 months left.

function lifeInWeeks(age) {
    var days = 365, weeks = 52, months = 12, yearsOld = 90;
    var remainingDays = (yearsOld * days) - (days * age);
    var remainingWeeks = (yearsOld * weeks) - (weeks * age);
    var remainingMonths = (yearsOld * months) - (months * age);
    console.log("You have " + remainingDays + " days, " + remainingWeeks + " weeks, and " + remainingMonths + " months left.");
}
lifeInWeeks(18);

